const $=id=>document.getElementById(id); let original=[],cleaned=[],name='data.csv',view='clean';
function parseCSV(text){text=text.replace(/^\uFEFF/,'');let rows=[],row=[],field='',quoted=false,after=false;for(let i=0;i<text.length;i++){let c=text[i];if(quoted){if(c==='"'){if(text[i+1]==='"'){field+='"';i++}else{quoted=false;after=true}}else field+=c}else if(after){if(c===','){row.push(field);field='';after=false}else if(c==='\r'||c==='\n'){row.push(field);rows.push(row);row=[];field='';after=false;if(c==='\r'&&text[i+1]==='\n')i++}else throw Error('Unexpected character after a closing quote.')}else if(c==='"'){if(field)throw Error('Unexpected quote inside an unquoted field.');quoted=true}else if(c===','){row.push(field);field=''}else if(c==='\r'||c==='\n'){row.push(field);rows.push(row);row=[];field='';if(c==='\r'&&text[i+1]==='\n')i++}else field+=c}if(quoted)throw Error('A quoted field was not closed.');if(field!==''||row.length||after){row.push(field);rows.push(row)}return rows}
function load(text,filename){try{const data=parseCSV(text);if(!data.length)throw Error('This file is empty.');const width=data[0].length;if(data.some(r=>r.length!==width))throw Error('Rows have different numbers of columns. Check the delimiter and quoting in your file.');original=data;name=filename;view='clean';$('filename').textContent=name;$('drop').hidden=true;$('workspace').hidden=false;$('error').textContent='';update()}catch(e){alert('Could not open CSV: '+e.message)}}
function update(){if(!original.length)return;const trim=$('trim').checked,empty=$('empty').checked,dedupe=$('dedupe').checked,headers=$('headers').checked;let seen=new Set(),removed=0,changes=0;cleaned=[];original.forEach((r,i)=>{let cells=r.map((v,j)=>{let n=trim?v.trim():v;if(i===0&&headers)n=n.trim().replace(/\s+/g,'_');if(n!==v)changes++;return n});if(i>0&&empty&&cells.every(x=>x.trim()==='')){removed++;return}let key=JSON.stringify(cells);if(i>0&&dedupe&&seen.has(key)){removed++;return}if(i>0)seen.add(key);cleaned.push({cells,source:r,index:i})});$('fileinfo').textContent=`${original.length-1} rows · ${original[0].length} columns`;$('summary').textContent=`${changes} cells changed · ${removed} rows removed · ${cleaned.length-1} rows ready`;$('cleanTab').classList.toggle('active',view==='clean');$('originalTab').classList.toggle('active',view==='original');let data=view==='clean'?cleaned:original.map((cells,index)=>({cells,source:cells,index}));$('thead').replaceChildren();$('tbody').replaceChildren();const make=(tag,value)=>{let e=document.createElement(tag);e.textContent=value; e.title=value;return e};let head=document.createElement('tr');head.append(make('th','#'));data[0].cells.forEach(v=>head.append(make('th',v)));$('thead').append(head);data.slice(1,101).forEach(r=>{let tr=document.createElement('tr');tr.append(make('td',String(r.index)));r.cells.forEach((v,i)=>{let td=make('td',v);if(view==='clean'&&v!==r.source[i])td.className='changed';tr.append(td)});$('tbody').append(tr)});$('viewcount').textContent=`${Math.min(100,data.length-1)} of ${data.length-1} rows`}
function download(){let csv=cleaned.map(r=>r.cells.map(v=>/[",\r\n]/.test(v)?'"'+v.replace(/"/g,'""')+'"':v).join(',')).join('\r\n');let a=document.createElement('a');a.href=URL.createObjectURL(new Blob(['\ufeff',csv],{type:'text/csv;charset=utf-8'}));a.download=name.replace(/\.csv$/i,'')+'-clean.csv';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
$('choose').onclick=$('replace').onclick=()=>$('file').click();$('file').onchange=async e=>{let f=e.target.files[0];if(f)load(await f.text(),f.name);e.target.value=''};$('demo').onclick=()=>load('Name,Email,City\r\n  Maya Smith  , maya@example.com ,Amman\r\nOmar Ali,OMAR@example.com,London\r\n  Maya Smith  , maya@example.com ,Amman\r\n,,\r\nLina Haddad,lina@example.com,Paris','example.csv');['trim','empty','dedupe','headers'].forEach(id=>$(id).onchange=update);$('download').onclick=download;$('cleanTab').onclick=()=>{view='clean';update()};$('originalTab').onclick=()=>{view='original';update()};let drop=$('drop');drop.ondragover=e=>{e.preventDefault();drop.style.borderColor='#315f46'};drop.ondragleave=()=>drop.style.borderColor='';drop.ondrop=async e=>{e.preventDefault();drop.style.borderColor='';let f=e.dataTransfer.files[0];if(f)load(await f.text(),f.name)};

